//! The pin identity trait.

use crate::gpio::Sealed;

/// Identity of a pin: an Arduino header (`D6`) or a board-internal pin
/// (`UsbMux`), generated by [`pin_map`](crate::gpio::pin_map). Sealed.
pub trait PinId: Sealed + Copy {
    /// Common name: the header name (`"D6"`) or the board-internal name
    /// (`"UsbMux"`).
    const NAME: &'static str;
    /// The RA4M1 port pin behind it (`"P111"`): the name the hardware
    /// manual uses.
    const PORT_PIN: &'static str;
    /// Port digit, `'0'`–`'9'` (`'1'` for P111).
    const PORT: char;
    /// Pin index within the port, 0–15 (`11` for P111).
    const PIN: u8;
}
